PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS admin (id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id INTEGER PRIMARY KEY, attempted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL, ruc TEXT UNIQUE, email TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS licenses (id INTEGER PRIMARY KEY, client_id INTEGER NOT NULL REFERENCES clients(id), reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'BORRADOR', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authorized_devices (id INTEGER PRIMARY KEY, license_id INTEGER NOT NULL REFERENCES licenses(id), installation_id TEXT NOT NULL UNIQUE, label TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activations (id INTEGER PRIMARY KEY, device_id INTEGER NOT NULL REFERENCES authorized_devices(id), status TEXT NOT NULL DEFAULT 'PENDIENTE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recovery_requests (id INTEGER PRIMARY KEY, device_id INTEGER NOT NULL REFERENCES authorized_devices(id), status TEXT NOT NULL DEFAULT 'PENDIENTE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS history (id INTEGER PRIMARY KEY, event TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES ('panel_name','Panel Central EDUXFAC');
